package main

import (
	"bufio"
	"fmt"
	"os"
)

func main() {
	in := bufio.NewReader(os.Stdin)
	var x int64
	fmt.Fscan(in, &x)

	// Normalize camera angle to [0, 360)
	xMod := x % 360
	if xMod < 0 {
		xMod += 360
	}

	bestTurns := int64(0)
	bestDev := int64(1<<62) // large number

	for k := int64(0); k < 4; k++ {
		// total image rotation clockwise: camera (xMod) + k*90
		total := xMod + k*90
		// deviation from vertical is minimal angle to 0 modulo 360
		dev := total % 360
		if dev > 180 {
			dev = 360 - dev
		}
		if dev < bestDev {
			bestDev = dev
			bestTurns = k
		}
	}

	fmt.Println(bestTurns)
}

