package main

import (
	"bufio"
	"fmt"
	"os"
)

func absInt64(a int64) int64 {
	if a < 0 {
		return -a
	}
	return a
}

func main() {
	in := bufio.NewReader(os.Stdin)
	var x int64
	fmt.Fscan(in, &x)

	x = ((x % 360) + 360) % 360

	bestTurns := int64(0)
	bestDev := absInt64(x)

	for k := int64(1); k <= 3; k++ {
		angle := x + 90*k
		angle = ((angle % 360) + 360) % 360
		if angle > 180 {
			angle = 360 - angle
		}
		dev := absInt64(angle)
		if dev < bestDev {
			bestDev = dev
			bestTurns = k
		}
	}

	fmt.Println(bestTurns)
}
